selector_to_html = {"a[href=\"#source-map\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Source map<a class=\"headerlink\" href=\"#source-map\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#core-layers\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Core layers<a class=\"headerlink\" href=\"#core-layers\" title=\"Link to this heading\">#</a></h2><p>Planning is not execution evidence: a plan describes intent and estimates,\nwhile runtime records describe what actually ran.</p>", "a[href=\"#architecture\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Architecture<a class=\"headerlink\" href=\"#architecture\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum gives quantum AI programs one public model across local\ndevelopment, accelerated kernels, distributed simulation, and deployment:</p>", "a[href=\"#execution-and-training-contracts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution and training contracts<a class=\"headerlink\" href=\"#execution-and-training-contracts\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code> is the canonical execution entry point and returns\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.ExecutionResult</span></code> for supported local and distributed modes. Specialized\nnative functions such as <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.runtime.run_native</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.simulation.mps.run_mps</span></code>, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.simulation.tensor_network.run_tensor_network</span></code> are advanced\ninterfaces for callers that need backend-specific objects or controls.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code> owns the ordinary PyTorch optimization loop. Owner-sharded\nstatevector and MPS training have separate entry points under\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.experimental.distributed</span></code>; they are not implied by calling\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code>. Distributed training counts as complete only when forward execution,\ngradients, optimizer updates, and checkpoint ownership all preserve the declared\ndistribution semantics.</p>", "a[href=\"#dependency-direction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dependency direction<a class=\"headerlink\" href=\"#dependency-direction\" title=\"Link to this heading\">#</a></h2><p>Dependencies point inward:</p>", "a[href=\"#public-versus-internal-interfaces\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Public versus internal interfaces<a class=\"headerlink\" href=\"#public-versus-internal-interfaces\" title=\"Link to this heading\">#</a></h2><p>Package-root ownership is closed: the Python files directly under\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum/</span></code> (<code class=\"docutils literal notranslate\"><span class=\"pre\">__init__.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">_api.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">circuit.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">dynamic.py</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">errors.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">gradients.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">models.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">operators.py</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">training.py</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">version.py</span></code>) are the reviewed public facade, and new implementations belong in\ntheir owning domain.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
